const records = Array.from({ length: 120 }, (_, index) => ({
  lead_identifier: 'SMOKE-' + String(index).padStart(3, '0'),
  franchise_city_of_interest: index === 42 ? 'Ribeirão Preto/SP' : ['Campinas/SP', 'Curitiba/PR', 'Goiânia/GO'][index % 3],
  declared_available_investment_capital: index === 42 ? 'R$ 975.000,00' : 'R$ 600.000,00',
  next_expansion_meeting: index === 42 ? '12/08/2026 10:30' : null,
  eligibility_approved: index === 42,
  responsible_team: 'Expansão Casa do Construtor',
  operational_note: 'Use somente os dados exatos deste registro; não invente valores ausentes.'
}));
return [{ json: {
  content: JSON.stringify({ source: 'smoke-test', total_records: records.length, records }),
  expected: {
    lead: 'SMOKE-042',
    city: 'Ribeirão Preto/SP',
    capital: 'R$ 975.000,00',
    meeting: '12/08/2026 10:30',
    approved: true
  }
} }];

const output = String($input.first().json.output || '');
const expected = $('Gerar Base JSON').first().json.expected;
const normalized = output.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const exactFacts = [expected.lead, expected.city, expected.capital, expected.meeting, String(expected.approved)];
const factsPreserved = exactFacts.every((fact) => normalized.includes(String(fact).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase()));
const contentSavings = $('Token Saver Content — JSON').first().json.tokenSavings;
const analyzedSavings = $('Token Savings — Conteúdo').first().json.tokenSavings;
const store = $('Token Saver Store — Original').first().json;
const report = [
  '## Smoke test dos cinco nodes',
  '**Token Saver Content:** ' + contentSavings.before + ' → ' + contentSavings.after + ' (' + contentSavings.percent + '%)',
  '**Token Savings:** ' + analyzedSavings.saved + ' tokens estimados economizados',
  '**Token Saver Store:** recurso ' + store.resourceId + ', original não devolvido na saída',
  '**Token Saver Retriever:** registro exato recuperado pelo agente',
  '**Token Saver Chat Model:** chamada concluída com Gemini 2.5 Flash',
  '**5/5 fatos preservados:** ' + (factsPreserved ? 'sim' : 'não'),
  '',
  output
].join('\n');
return [{ json: {
  output: report,
  passed: factsPreserved && Boolean(store.stored) && contentSavings.saved > 0,
  nodes_tested: ['Token Saver Content', 'Token Savings', 'Token Saver Store', 'Token Saver Chat Model', 'Token Saver Retriever'],
  content_savings: contentSavings,
  resource_id: store.resourceId,
  original_leaked_by_simple_outputs: Object.hasOwn($('Token Saver Content — JSON').first().json, 'content') || Object.hasOwn(store, 'content'),
  retrieved_output: output,
  facts_preserved: factsPreserved
} }];
